pub fn max(a: &Vec<i32>, n: usize) -> i32 {
    assert!(n > 0, "n must be > 0");
    assert!(n <= a.len(), "n must be <= a.len()");

    let mut m = a[0];
    for &x in a.iter().take(n).skip(1) {
        if x > m {
            m = x;
        }
    }
    m
}

